def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = 4

    # Find a full row or column of 2s, the barrier.
    barrier = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            barrier = ("h", r)
            break
    if barrier is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                barrier = ("v", c)
                break
    if barrier is None:
        return out

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    rmin = min(r for r, c in cells)
    rmax = max(r for r, c in cells)
    cmin = min(c for r, c in cells)
    cmax = max(c for r, c in cells)

    if barrier[0] == "h":
        wall = barrier[1]
        if (rmin + rmax) // 2 < wall:
            dr = wall - 1 - rmax
            marker_r = rmin + dr - 1
        else:
            dr = wall + 1 - rmin
            marker_r = rmax + dr + 1

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + dr][c] = grid[r][c]
        if 0 <= marker_r < h:
            out[marker_r] = [8] * w

    else:
        wall = barrier[1]
        if (cmin + cmax) // 2 < wall:
            dc = wall - 1 - cmax
            marker_c = cmin + dc - 1
        else:
            dc = wall + 1 - cmin
            marker_c = cmax + dc + 1

        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + dc] = grid[r][c]
        if 0 <= marker_c < w:
            for r in range(h):
                out[r][marker_c] = 8

    return out
